    { id=18635, tab=3, tier=2, col=0, name="Vindication", icon="spell_holy_vindication", maxRank=3, prereqTalent=0, prereqPoints=10, wired=true, tooltip={ "Gives the Paladin's damaging melee attacks a chance to reduce the target's Strength and Agility by 5% for 10 sec.", "Gives the Paladin's damaging melee attacks a chance to reduce the target's Strength and Agility by 10% for 10 sec.", "Gives the Paladin's damaging melee attacks a chance to reduce the target's Strength and Agility by 15% for 10 sec." }, localized={deDE={name="Recht und Ordnung", tooltip={ "Die Schaden verursachenden Nahkampfangriffe des Paladins haben eine Chance, die Stärke und Beweglichkeit des Ziels 10 Sek. lang um 5% zu verringern.", "Die Schaden verursachenden Nahkampfangriffe des Paladins haben eine Chance, die Stärke und Beweglichkeit des Ziels 10 Sek. lang um 10% zu verringern.", "Die Schaden verursachenden Nahkampfangriffe des Paladins haben eine Chance, die Stärke und Beweglichkeit des Ziels 10 Sek. lang um 15% zu verringern." }}} },
