    { id=18637, tab=3, tier=2, col=2, name="Seal of Command", icon="ability_warrior_innerrage", maxRank=1, prereqTalent=0, prereqPoints=10, wired=true, tooltip={ "Gives the Paladin a chance to deal additional Holy damage equal to 70% of the damage of the attack. Only one Seal can be active on the Paladin at any one time. Lasts 30 sec. Unleashing this Seal's energy will judge an enemy, instantly causing 68 to 74 Holy damage, 137 to 147 if the target is stunned." }, grant={ [1]=932606 }, localized={deDE={name="Siegel des Befehls", tooltip={ "Gewährt dem Paladin eine Chance, zusätzlichen Heiligschaden in Höhe von 70% des Angriffsschadens zu verursachen. Auf dem Paladin kann immer nur ein Siegel gleichzeitig aktiv sein. Hält 30 Sek. lang an. Das Entfesseln der Energie dieses Siegels richtet einen Feind und verursacht sofort 68 bis 74 Heiligschaden oder 137 bis 147, wenn das Ziel betäubt ist." }}} },
