    { id=18642, tab=3, tier=4, col=2, name="Sanctity Aura", icon="spell_holy_mindvision", maxRank=1, prereqTalent=0, prereqPoints=20, wired=true, tooltip={ "Increases Holy damage done by party members within 30 yards by 10%. Players may only have one Aura on them per Paladin at any one time." }, grant={ [1]=932602 }, localized={deDE={name="Aura der Heiligkeit", tooltip={ "Erhöht den verursachten Heiligschaden von Gruppenmitgliedern im Umkreis von 30 Metern um 10%. Spieler können von jedem Paladin immer nur eine Aura gleichzeitig erhalten." }}} },
    { id=18643, tab=3, tier=5, col=1, name="Vengeance", icon="ability_racial_avatar", maxRank=5, prereqTalent=18636, prereqPoints=25, wired=true, tooltip={ "Gives you a 3% bonus to Physical and Holy damage you deal for 8 sec after dealing a critical strike from a swing, spell or ability.", "Gives you a 6% bonus to Physical and Holy damage you deal for 8 sec after dealing a critical strike from a swing, spell or ability.", "Gives you a 9% bonus to Physical and Holy damage you deal for 8 sec after dealing a critical strike from a swing, spell or ability.", "Gives you a 12% bonus to Physical and Holy damage you deal for 8 sec after dealing a critical strike from a swing, spell or ability.", "Gives you a 15% bonus to Physical and Holy damage you deal for 8 sec after dealing a critical strike from a swing, spell or ability." }, localized={deDE={name="Rache", tooltip={ "Gewährt Euch nach einem kritischen Treffer mit einem Schlag, Zauber oder einer Fähigkeit 8 Sek. lang einen Bonus von 3% auf Euren verursachten körperlichen Schaden und Heiligschaden.", "Gewährt Euch nach einem kritischen Treffer mit einem Schlag, Zauber oder einer Fähigkeit 8 Sek. lang einen Bonus von 6% auf Euren verursachten körperlichen Schaden und Heiligschaden.", "Gewährt Euch nach einem kritischen Treffer mit einem Schlag, Zauber oder einer Fähigkeit 8 Sek. lang einen Bonus von 9% auf Euren verursachten körperlichen Schaden und Heiligschaden.", "Gewährt Euch nach einem kritischen Treffer mit einem Schlag, Zauber oder einer Fähigkeit 8 Sek. lang einen Bonus von 12% auf Euren verursachten körperlichen Schaden und Heiligschaden.", "Gewährt Euch nach einem kritischen Treffer mit einem Schlag, Zauber oder einer Fähigkeit 8 Sek. lang einen Bonus von 15% auf Euren verursachten körperlichen Schaden und Heiligschaden." }}} },
